"""Invented621 interface fixtures only, never a real retained-P6 or body call.

The compressed JSON fixtures were produced once from the upstream explicitly
SYNTHETIC fixed-dimension fixture, with invented material rates, not actual
contexts/prices. Decoding does not execute any upstream producer. They preserve
its full schema so metadata/geometry loss is tested across the real interface.
"""
from copy import deepcopy
from math import isclose,pi
import base64,json,zlib
import pytest
from engineering.railway_project import header_component as h
POSITIVE = ''
NEGATIVE = ''


def fixture(side=1):
    raw=json.loads(zlib.decompress(base64.b64decode(POSITIVE if side==1 else NEGATIVE)))
    return raw,pin(raw)


def pin(raw):
    return dict(source_commit=h.SOURCE_COMMIT,source_module_sha256=h.SOURCE_SHA256,evaluation_id=raw['evaluation_id'],physical_definition_id=raw['physical_definition_id'],source_request_id=raw['source_binding']['request_id'],source_execution_id='e'*64)


def reseal(raw):
    p=raw['physical_definition'];p['new_parts']=[{k:deepcopy(x[k]) for k in ('id','material','quantity','frame','geometry','at_m','rotation','role')} for x in raw['parts']]
    p['source_finished_geometry']=[{k:deepcopy(x[k]) for k in ('source_id','material_id','frame','at_m','rotation','geometry')} for x in raw['source_finished_successors']]
    p['welds']=[{k:deepcopy(x[k]) for k in ('material','parents','paths_m','profiles','leg_m')} for x in raw['welds']]
    raw['physical_definition_id']=h.identity(p);raw.pop('evaluation_id',None);raw['evaluation_id']=h.identity(raw)
    return pin(raw)


@pytest.mark.parametrize('side',[-1,1])
def test_complete_nonadmitted_draft_preserves_six_required_contracts_and_source_ownership(side):
    raw,p=fixture(side);before=deepcopy((raw,p));out=h.normalize(raw,pin=p,request_id='a'*64)
    assert (raw,p)==before and out['canonical_definition'] is None and not out['canonical_admitted']
    d=out['canonical_draft'];assert len(d['stock_groups'])==40 and len(d['entities'])==47
    assert len(d['required_counterpart_ids'])==6 and not d['all_required_interfaces_resolved']
    assert len([x for x in d['physical_interfaces'] if x['schema']=='osr-header-blind-isolated-stack/1'])==4
    assert all(x['status'].startswith('required-unresolved') for x in d['physical_interfaces'])
    assert {'canonical-geometry-domain','blind-isolated-stack','source-key-map','bounded-mass-properties','native-structural-access','lifecycle-tools-fixture'}<=set(x['code'] for x in out['held_facts'])
    assert out['source_ownership']['retained_P6_joinery_ids']==raw['source_ownership']['retained_P6_joinery_ids']
    assert out['unlocated_old_joinery_credit'] is None and not out['source_finished_budget_transfers_applied']
    assert out['shared_workshop_allocations']['quantity_per_family']==1 and not out['shared_workshop_allocations']['installed']
    assert out['shared_workshop_allocations']['price_USD'] is None
    assert all(out[k] is False for k in h.FLAGS)
    assert out['component_geometry_id']==h.identity(out['physical_definition'])


@pytest.mark.parametrize('side',[-1,1])
def test_signed_source_pose_and_roundV_to_canonicalX_are_proper_without_second_lift(side):
    raw,p=fixture(side);o=h.normalize(raw,pin=p,request_id='a'*64);d=o['canonical_draft'];placement=d['placement_in_source_frame']
    assert placement['at_m'][2]==pytest.approx(1.0195)
    assert placement['rotation']==(h.I if side==1 else [[-1.,0.,0.],[0.,-1.,0.],[0.,0.,1.]])
    for e in d['entities']:
        h.proper(e['rotation'])
        if e['id'].startswith('bush/'):
            assert e['geometry']['kind']=='annulus' and e['rotation']==h.Y_ROUND
            assert [e['rotation'][k][0] for k in range(3)]==[0,1,0]
            assert e['at_m'][1]==pytest.approx(.01325)
    ends=[e for e in d['entities'] if e.get('source_id')==raw['physical_definition']['source_geometry']['endplate']['id']]
    assert len(ends)==1 and ends[0]['at_m']==pytest.approx([0,.014,0])
    m=ends[0]['normal_form_mass_properties'];assert m['frame']=='joint-local-UVW'
    assert m['centroid_interval_m'][1][0]<.014<m['centroid_interval_m'][1][1]
    assert m['exact_point_CG_or_tensor'] is False


def test_welds_split_into_six_proper_triangles_under_only_two_stock_owners():
    raw,p=fixture();o=h.normalize(raw,pin=p,request_id='a'*64);d=o['canonical_draft'];es={x['id']:x for x in d['entities']}
    for i in range(2):
        stock=next(s for s in d['stock_groups'] if s['id']=='new/weld/'+str(i));assert len(stock['entity_ids'])==3
        assert sum(stock['cost_shares'].values())==pytest.approx(1)
        for n,eid in enumerate(stock['entity_ids']):
            e=es[eid];assert e['geometry']['kind']=='triangle-prism';h.proper(e['rotation'])
            profile=raw['parts'][[x['id'] for x in raw['parts']].index('weld/'+str(i))]['geometry']['profiles'][n]
            points=[]
            for t in profile['interval_m']:
                for a,b in profile['vertices_m']:
                    q=[0.,0.,0.];q[profile['extrusion_axis']]=t;q[profile['section_axes'][0]]=a;q[profile['section_axes'][1]]=b;points.append(q)
            actual=[h.add(e['at_m'],h.apply(e['rotation'],v)) for v in e['geometry']['vertices_m']]
            for got,want in zip(sorted(actual),sorted(points)):assert got==pytest.approx(want)
        assert stock['net_mass_label_cases_kg']==raw['materials']['rows'][[x['part_id'] for x in raw['materials']['rows']].index('weld/'+str(i))]['mass_bounds_kg']


def test_complete_finite_corner_bounds_moments_and_onceonly_source_blank_survive():
    raw,p=fixture();o=h.normalize(raw,pin=p,request_id='a'*64);d=o['canonical_draft']
    for x in raw['source_finished_successors']:
        e=next(e for e in d['entities'] if e['id']==x['successor_id']);s=next(s for s in d['stock_groups'] if s.get('source_predecessor')==x['source_id'])
        assert e['geometry']==x['geometry'] and e['source_material_properties']==x['material_properties']
        assert s['budget_transfer']==x['gross_budget'] and s['additional_raw_material_purchase_USD']==0
        assert s['disposition']=='finish_new_source_blank_REQUIRED_NOT_APPLIED'
        assert e['normal_form_mass_properties']['exact_point_CG_or_tensor'] is False
    steel=raw['source_finished_successors'][1]
    assert len(steel['geometry']['minimum_void_union'])==8
    assert steel['geometry']['thread_specification']['flat_bottom_corner_radius_hypothesis_m']==.00005
    assert o['source_machining']==raw['machining'] and o['source_manufacturing_definition']==raw['manufacturing_definition']


def test_unsupported_supplier_allocations_stay_graphs_with_unknown_geometry_not_filled_solids():
    raw,p=fixture();o=h.normalize(raw,pin=p,request_id='a'*64);es={x['id']:x for x in o['canonical_draft']['entities']}
    for name in ('thread-compound','seal-top-and-sides','steel-weld-repair-finish','M8x40/-0.08/-0.05','lock0/-0.08/-0.05'):
        assert es[name]['geometry']['kind']=='unresolved-material-graph'
        assert es[name]['geometry']['source_geometry']==next(x['geometry'] for x in raw['parts'] if x['id']==name)
        assert es[name]['mass_properties']['centroid_local_m'] is None
    for c in o['canonical_draft']['physical_interfaces'][:4]:
        assert c['physical_specification']['bush_does_not_span_blind_receiver']
        assert c['physical_specification']['isolation_bush_interval_v_m']==[0,.0265]
        assert c['physical_specification']['receiver_interval_v_m']==[-.010,0]
        assert c['schema']!='osr-coaxial-through-stack/1'


def test_cost_and_QA_changes_affect_evaluation_not_component_geometry():
    raw,p=fixture();a=h.normalize(raw,pin=p,request_id='a'*64)
    raw['materials']['rows'][0]['process_QA_USD']=[x+1 for x in raw['materials']['rows'][0]['process_QA_USD']]
    raw['stack']['locking_function_qualified']=True
    p=reseal(raw);b=h.normalize(raw,pin=p,request_id='b'*64)
    assert a['component_geometry_id']==b['component_geometry_id'] and a['evaluation_id']!=b['evaluation_id']


def test_unknown_prices_stayNone_and_generate_named_hold():
    raw,p=fixture();raw['materials']['rows'][0]['gross_material_USD']=None;p=reseal(raw);o=h.normalize(raw,pin=p,request_id='a'*64)
    s=next(x for x in o['canonical_draft']['stock_groups'] if x['source_owner_id']=='isolation-pad')
    assert s['direct_cost_label_cases_USD'] is None
    assert any(x['code']=='unknown-stock-price-or-density' for x in o['held_facts'])


@pytest.mark.parametrize('change',['seal','physical','source','request','mode','parts','accounts','mirror','washer','bush','firstmoment','net','budget','corner','void','substrate'])
def test_invalid_or_inconsistent_source_domains_refuse_without_mutation(change):
    raw,p=fixture()
    if change=='seal':raw['evaluation_id']='0'*64
    elif change=='physical':raw['physical_definition_id']='0'*64
    elif change=='source':p['source_commit']='0'*40
    elif change=='request':p['source_request_id']='0'*64
    else:
        if change=='mode':raw['manufacturing_definition']['mode']='modify-authenticated-existing';raw['manufacturing_definition_id']=h.identity(raw['manufacturing_definition'])
        elif change=='parts':raw['parts'].pop()
        elif change=='accounts':raw['materials']['rows'].append(deepcopy(raw['materials']['rows'][0]))
        elif change=='mirror':raw['physical_definition']['frame']['rotation'][0][0]=-1
        elif change=='washer':next(x for x in raw['parts'] if x['id']=='steelwasher/-0.08/-0.05')['at_m'][1]+=.001
        elif change=='bush':next(x for x in raw['parts'] if x['id']=='bush/-0.08/-0.05')['geometry']['length_m']+=.010
        elif change=='firstmoment':raw['source_finished_successors'][1]['material_properties']['bounding_shape_conservation'][0]['net_local_first_moment_m4'][1]+=.000001
        elif change=='net':raw['source_finished_successors'][1]['material_properties']['net_volume_interval_m3'][0]+=.000001
        elif change=='budget':raw['source_finished_successors'][0]['gross_budget']['quantity_transferred']=2
        elif change=='corner':raw['source_finished_successors'][1]['geometry']['thread_specification']['flat_bottom_corner_radius_hypothesis_m']=.0001
        elif change=='void':raw['source_finished_successors'][1]['geometry']['minimum_void_union'].pop()
        elif change=='substrate':raw['source_finished_successors'][0]['at_m'][2]+=.150
        p=reseal(raw)
    before=deepcopy((raw,p))
    with pytest.raises((ValueError,KeyError)):h.normalize(raw,pin=p,request_id='a'*64)
    assert (raw,p)==before


@pytest.mark.parametrize('value',[True,float('nan'),float('inf')])
def test_nonfinite_or_boolean_geometric_values_refuse(value):
    with pytest.raises(ValueError):h.vector([0,value,0])


def test_parallel_circle_union_independent_disjoint_and_coaxial_controls():
    a=dict(axis=1,at_m=[0,0,0],radius_m=.002,length_m=.01);b=deepcopy(a);b['radius_m']=.001
    assert h._union([a,b,a],[.2,.025,.18])==h._union([a],[.2,.025,.18])
    b['at_m'][0]=1e-16
    with pytest.raises(ValueError,match='noncoaxial'):h._union([a,b],[.2,.025,.18])


def test_axial_roundtrip_ULP_check_does_not_move_or_merge_physical_source_cuts():
    raw,p=fixture();g=raw['source_finished_successors'][1]['geometry'];before=deepcopy(g)
    replay=h._union(g['maximum_void_union'],g['size_m']);assert h._same_union(replay,g['maximum_void_union'])
    shifted=deepcopy(replay);shifted[0]['at_m'][0]+=1e-16;assert not h._same_union(shifted,replay)
    shifted=deepcopy(replay);shifted[0]['at_m'][1]+=1e-12;assert not h._same_union(shifted,replay)
    o=h.normalize(raw,pin=p,request_id='a'*64)
    out=next(e['geometry'] for e in o['canonical_draft']['entities'] if e.get('source_id')==raw['source_finished_successors'][1]['source_id'])
    assert out==before and g==before


@pytest.mark.parametrize('change',['unit','pad-axis','round-extra','weld-drawing','machining-projection','ownership','installed-drawing'])
def test_additional_physical_fields_are_preserved_or_refused_never_silently_omitted(change):
    raw,p=fixture()
    if change=='unit':next(x for x in raw['parts'] if x['id'].startswith('bush/'))['geometry']['units']='mm'
    elif change=='pad-axis':raw['parts'][0]['geometry']['holes'][0]['axis']=True
    elif change=='round-extra':next(x for x in raw['parts'] if x['id'].startswith('bush/'))['geometry']['hidden_void']={'radius_m':.001}
    elif change=='weld-drawing':next(x for x in raw['parts'] if x['id']=='weld/0')['geometry']['paths_m'][0][0][0]+=.001
    elif change=='machining-projection':raw['physical_definition']['planned_source_machining'][0]['hidden_cut']=True
    elif change=='ownership':raw['source_finished_successors'][0]['source_record_id']='0'*64
    else:raw['manufacturing_definition']['new_drawing']['state']='installed';raw['manufacturing_definition_id']=h.identity(raw['manufacturing_definition'])
    p=reseal(raw)
    with pytest.raises(ValueError):h.normalize(raw,pin=p,request_id='a'*64)


